{noformat}import {PeriodType, ScheduleHelper} from "@server-legacy/common/invoicing/helper/scheduleHelper";

describe("Schedule Helper tests", () => {

    const tz = "Europe/Berlin";

    it("saturday 23h59", () => {
        expect(ScheduleHelper.periodDescriptorFromTs(1704581999, tz, PeriodType.WEEKLY))
            .toEqual("y2024w1");
    });

    it("sunday 00h00", () => {
        expect(ScheduleHelper.periodDescriptorFromTs(1704582000, tz, PeriodType.WEEKLY))
            .toEqual("y2024w1");
    });

    it("sunday 23h59", () => {
        expect(ScheduleHelper.periodDescriptorFromTs(1704668399, tz, PeriodType.WEEKLY))
            .toEqual("y2024w1");
    });

    it("monday 0h00", () => {
        expect(ScheduleHelper.periodDescriptorFromTs(1704668400, tz, PeriodType.WEEKLY))
            .toEqual("y2024w2");
